function applyDiscount(user: User | null, orderAmount: number) {
  if (user) {
    if (user.isActive) {
      if (user.loyaltyPoints > 100) {
        if (!user.accountSuspended) {
          return orderAmount * 0.8;
        }
      }
    }
  }
  return orderAmount;
}

function processPayment(order: Order) {
  if (order != null) {
    if (order.customer) {
      if (order.customer.isVerified) {
        if (order.total > 0) {
          chargeCard(order);
        }
      }
    }
  }
}

/* Version A: guard clauses */
function fulfillOrder(order: Order | null) {
  if (!order) return;
  if (!order.customer) return;
  if (!order.isPaid) return;
  ship(order);
}

/* Version B: nested conditionals */
function fulfillOrderNested(order: Order | null) {
  if (order) {
    if (order.customer) {
      if (order.isPaid) {
        ship(order);
      }
    }
  }
}
